def get_plant_data(plant_period):
    # Find the scope node
    scope_node = None
    for node in doc['nodes']:
        if node['title'] == plant_period:
            scope_node = node
            break

    if not scope_node:
        return None

    # Get Products table
    products_node = None
    ledger_node = None
    for node in doc['nodes']:
        if node['parent_id'] == scope_node['node_id']:
            if 'Products' in node['title']:
                products_node = node
            elif 'Daily ledger' in node['title']:
                ledger_node = node

    products_data = {}
    prod_rows = table_rows(products_node)
    for idx, row in prod_rows:
        # columns: ['product', 'group', 'sub-group', 'storage location', 'kg per unit', 'opening stock']
        p = row['product']
        products_data[p] = {
            'kg_per_unit': float(row['kg per unit']),
            'opening_stock': int(row['opening stock'])
        }

    ledger_rows = table_rows(ledger_node)
    daily_data = {} # day -> {product -> {produced, ordered}}
    for idx, row in ledger_rows:
        day = int(row['day'])
        prod = row['product']
        if day not in daily_data:
            daily_data[day] = {}
        daily_data[day][prod] = {
            'produced': int(row['produced']),
            'ordered': int(row['ordered'])
        }

    return products_data, daily_data

