def simulate(products, ledger, capacity, modified_order=None):
    stock = {p: data['opening_stock'] for p, data in products.items()}
    backordered = {p: 0 for p in products}
    order_queue = [] 
    order_counter = 0
    results = {} 

    days = sorted(ledger.keys())
    for day in days:
        results[day] = {}
        for p in products:
            stock[p] += ledger[day][p]['produced']

        for p in products:
            ordered_qty = ledger[day][p]['ordered']
            if modified_order and modified_order[0] == day and modified_order[1] == p:
                ordered_qty = modified_order[2]
            if ordered_qty > 0:
                order_queue.append([p, ordered_qty, day, order_counter])
                order_counter += 1

        order_queue.sort(key=lambda x: (x[2], x[1], x[0]))

        remaining_capacity = capacity
        shipped_today = {p: 0 for p in products}

        for order in order_queue:
            p, qty, day_placed, order_id = order
            weight_per_unit = products[p]['kg_per_unit']
            max_by_stock = stock[p]
            max_by_capacity = int(remaining_capacity // weight_per_unit)
            units_to_ship = min(qty, max_by_stock, max_by_capacity)
            if units_to_ship > 0:
                stock[p] -= units_to_ship
                remaining_capacity -= units_to_ship * weight_per_unit
                shipped_today[p] += units_to_ship
                order[1] -= units_to_ship

        order_queue = [o for o in order_queue if o[1] > 0]

        for p in products:
            results[day][p] = {
                'shipped': shipped_today[p],
                'stock': stock[p],
                'backordered': sum(o[1] for o in order_queue if o[0] == p)
            }
    return results

