# 3. Planned production and orders for days 43-49
planned_data = get_table_data("Plant 2103, Period 03: Order book: Orders received and production planned for days 43 to 49")
future_events = {} # day -> product -> (production, ordered)
for row_idx, row in planned_data:
    day = int(row['day'])
    prod = row['product']
    if day not in future_events:
        future_events[day] = {}
    future_events[day][prod] = (int(row['planned production']), int(row['ordered']))

capacity_per_day = 407700

current_stock = stock_42.copy()
order_queue = backorders_42.copy()

run_out_days = {}

for day in range(43, 50):
    # 1. Production arrives
    if day in future_events:
        for prod, (prod_qty, _) in future_events[day].items():
            current_stock[prod] = current_stock.get(prod, 0) + prod_qty

    # 2. Orders join the queue
    if day in future_events:
        for prod, (_, ord_qty) in future_events[day].items():
            if ord_qty > 0:
                order_queue.append({'product': prod, 'day_placed': day, 'quantity': ord_qty})

    # 3. Dispatch
    # The policy: "Open orders are served one at a time, oldest first; among orders placed on the same day, 
    # the one with the smaller remaining quantity goes first, then the lower product code (alphabetical order)."
    # This sort must happen before serving.
    order_queue.sort(key=lambda x: (x['day_placed'], x['quantity'], x['product']))

    remaining_capacity = capacity_per_day

    new_order_queue = []
    for order in order_queue:
        prod = order['product']
        qty_needed = order['quantity']
        weight_per_unit = weights[prod]

        stock_available = current_stock.get(prod, 0)
        capacity_available_units = remaining_capacity // weight_per_unit

        can_ship = min(qty_needed, stock_available, int(capacity_available_units))

        if can_ship > 0:
            current_stock[prod] -= can_ship
            remaining_capacity -= can_ship * weight_per_unit
            remaining_qty = qty_needed - can_ship
        else:
            remaining_qty = qty_needed

        if remaining_qty > 0:
            new_order_queue.append({
                'product': prod,
                'day_placed': order['day_placed'],
                'quantity': remaining_qty
            })

    order_queue = new_order_queue

    # 4. Records and check for "run out of stock"
    for prod in weights:
        stock = current_stock.get(prod, 0)
        has_backorder = any(o['product'] == prod for o in order_queue)
        if stock == 0 and has_backorder:
            if prod not in run_out_days:
                run_out_days[prod] = day

