def simulate_with_order_tracking(capacity_change_day, new_capacity):
    stock = {p_id: p_info['opening_stock'] for p_id, p_info in products.items()}
    queue = [] # List of [product, quantity, day_placed, original_quantity, order_id]
    order_id_counter = 0

    results = {} 
    order_shipped_in_full_on_day_placed = {} # (prod, day_placed) -> bool

    for day in days:
        for prod, qty in daily_prod[day].items():
            stock[prod] += qty

        for prod, qty in daily_orders[day].items():
            if qty > 0:
                queue.append([prod, qty, day, qty, order_id_counter])
                order_id_counter += 1

        capacity = 300000 if day < capacity_change_day else new_capacity
        queue.sort(key=lambda x: (x[2], x[1], x[0]))

        day_shipped = collections.defaultdict(int)

        i = 0
        while i < len(queue):
            prod, qty, day_placed, original_qty, oid = queue[i]
            weight_per_unit = products[prod]['weight']

            max_by_stock = stock[prod]
            max_by_qty = qty
            max_by_cap = int(capacity // weight_per_unit)

            shipped_units = min(max_by_stock, max_by_qty, max_by_cap)

            if shipped_units > 0:
                stock[prod] -= shipped_units
                capacity -= shipped_units * weight_per_unit
                day_shipped[prod] += shipped_units
                queue[i][1] -= shipped_units

            if queue[i][1] == 0:
                # Order shipped in full
                if day == day_placed:
                    order_shipped_in_full_on_day_placed[(prod, day)] = True
                queue.pop(i)
            else:
                # Check if it was fully backordered on the day it was placed
                if day == day_placed and shipped_units == 0:
                    # Fully backordered (not shipped in full)
                    pass
                i += 1

        for prod in products:
            results[(day, prod)] = {'stock': stock[prod], 'shipped': day_shipped[prod]}

    return results, order_shipped_in_full_on_day_placed

