            'qty': int(row_data['units still open'])
        })

    # 4. Get Orders and Production for 141-147
    future_node = node_by_title(doc, 'Plant 1914, Period 10: Order book: Orders received and production planned for days 141 to 147')
    future_data = []
    for row_idx, row_data in table_rows(future_node):
        future_data.append({
