        for item in future_data:
            if item['day'] == day:
                prod = item['product']
                stock[prod] = stock.get(prod, 0) + item['prod']

        # 2. Orders join the queue
        for item in future_data:
            if item['day'] == day and item['ord'] > 0:
                queue.append({
                    'product': item['product'],
                    'day': day,
                    'qty': item['ord']
                })

        # 3. Dispatch
        daily_capacity = capacity_limit

        # The queue needs to be sorted every day for dispatch.
        # "Open orders are served one at a time, oldest first; among orders placed on the same day, the one with the smaller remaining quantity goes first, then the lower product code."

        # Create a list of currently open orders
        open_orders = [o for o in queue if o['qty'] > 0]
        # Sort them
        open_orders.sort(key=lambda x: (x['day'], x['qty'], x['product']))

